:root{--bg:#FFFFFF;--card:#FFFFFF;--ground:#F7F7F8;--ink:#1D1D1F;--muted:#6E6E73;--faint:#A1A1A6;--line:#E5E5EA;--line-strong:#D2D2D7;
--accent:#FFC400;--accent-hover:#F2B900;--accent-soft:#FFF6D6;--accent-ink:#8A6500;--ok:#1E7A46;--ok-soft:#E3F3E9;--warn:#9A5B00;--warn-soft:#FFF1D6;--bad:#B42318;--bad-soft:#FBE9E7;--info-soft:#EEF2F7;
--c1:#D99A00;--c2:#2E6FD6;--c3:#1FA463;--c4:#7B5CC7;--c5:#D9532B;
--display:'Manrope',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;--body:'Onest',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;
--r:18px;--r-s:11px;--shadow:0 1px 2px rgba(0,0,0,.04),0 12px 32px -12px rgba(29,29,31,.14)}
*{box-sizing:border-box}
html,body{margin:0;background:transparent;height:auto!important;min-height:0!important;overflow:auto}
body{color:var(--ink);font-family:var(--body);font-size:14px;line-height:1.45;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{font-family:var(--display)!important;margin:0;letter-spacing:-.01em;color:var(--ink)!important;font-weight:800}
a,a:visited,a:hover{color:inherit;text-decoration:none}
html,body{color:var(--ink)!important}
button{font:inherit;color:inherit}
.num{font-variant-numeric:tabular-nums}

.wrap{display:grid;gap:14px;padding:4px 2px 8px}
.row{display:flex;align-items:end;justify-content:space-between;gap:12px;flex-wrap:wrap}
.row h2{font-size:22px;font-weight:800}
.row .sub{color:var(--muted);margin-top:2px}
.card{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:16px 18px;box-shadow:var(--shadow);min-width:0}
.card h3{font-size:13px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}
.card .hd{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:10px;flex-wrap:wrap}
.drop{display:grid;place-items:center;gap:8px;text-align:center;border:2px dashed var(--line-strong);border-radius:var(--r);padding:34px 16px;cursor:pointer;background:var(--ground)}
.drop:hover,.drop.over{border-color:var(--accent);background:var(--accent-soft)}
.drop strong{font-family:var(--display);font-size:17px}
.drop .hint{color:var(--muted);font-size:13px}
.drop input{display:none}
.links{display:flex;gap:16px;flex-wrap:wrap;margin-top:12px;font-size:13px;color:var(--muted)}
.link{border:0;background:none;padding:0;color:var(--accent-ink);font-weight:600;cursor:pointer;text-decoration:underline;text-underline-offset:2px;font:inherit}
.btn{border:1px solid var(--line-strong);background:var(--card);border-radius:999px;padding:9px 16px;font-weight:600;cursor:pointer;color:var(--ink);font:inherit}
.btn:hover{border-color:var(--ink)}
.btn.primary{background:var(--accent);border-color:var(--accent);font-weight:700}
.btn.primary:hover{background:var(--accent-hover)}
.btn:disabled{opacity:.5;cursor:default}
.btn:focus-visible,.link:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent-ink);outline-offset:2px}
.chips{display:flex;gap:6px;flex-wrap:wrap}
.chip{border-radius:999px;padding:3px 10px;font-size:12px;font-weight:600;background:var(--info-soft);color:var(--muted)}
.chip.ok{background:var(--ok-soft);color:var(--ok)}
.chip.warn{background:var(--warn-soft);color:var(--warn)}
.chip.bad{background:var(--bad-soft);color:var(--bad)}
.notice{border-radius:var(--r-s);padding:10px 14px;background:var(--warn-soft);color:var(--warn);font-size:13px}
.notice.bad{background:var(--bad-soft);color:var(--bad)}
.notice.ok{background:var(--ok-soft);color:var(--ok)}
.tablewrap{overflow-x:auto}
table{border-collapse:collapse;width:100%;min-width:980px}
th{text-align:left;font-size:11px;font-weight:700;color:var(--faint);text-transform:uppercase;letter-spacing:.05em;padding:8px 6px;border-bottom:1px solid var(--line)}
td{padding:6px;border-bottom:1px solid var(--ground);vertical-align:top}
tr.off td{opacity:.55}
tr.bad td{background:#FFF8F7}
td input[type=checkbox]{width:16px;height:16px;margin-top:8px;accent-color:#8A6500;cursor:pointer}
td input:not([type=checkbox]),td select{width:100%;border:1px solid var(--line);border-radius:8px;padding:6px 8px;font:inherit;font-size:13px;background:var(--card);color:var(--ink)}
td input.amt{text-align:right;width:84px}
td select[data-f=payment]{min-width:158px}
td select[data-f=tier]{min-width:124px}
td .no{font-weight:700;white-space:nowrap}
td .items{color:var(--faint);font-size:12px;margin-top:3px}
td .st{font-size:12px;font-weight:600;line-height:1.35}
td .st.ok{color:var(--ok)}
td .st.warn{color:var(--warn)}
td .st.bad{color:var(--bad)}
td .st.muted{color:var(--faint)}
.foot{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-top:12px}
.foot .note{color:var(--faint);font-size:12px;max-width:640px}

