// "Качи поръчки": turns a shop's order export into the orders the portal will create.
//
// Pure functions, no DOM and no Appsmith, so the same file is inlined into the BoImport
// widget by bo-build-import.py AND run by import-parse.test.js under Node. Everything that
// decides what a merchant's file means lives here; the widget only draws it.
//
// Written 2026-09-30 for TheBasket.bg, whose shop (Seliton) can export orders to Excel but
// cannot talk to us any other way. Nothing here is Seliton-specific: the columns are found
// by their names, in Bulgarian or English, so any shop's export - or our own template -
// reads the same way. When a real Seliton export arrives, its column names go into FIELDS.

// Column names we recognise, per field, already normalised (see norm()). A header matches
// a field exactly, or - for names of four letters or more - by containing it; the longest
// match across all fields wins, which is what keeps "адрес за доставка" an address and
// "цена на доставка" a shipping cost rather than the delivery method.
const FIELDS = {
  order: ['номер', 'номер на поръчка', 'номер поръчка', 'поръчка', 'поръчка №', '№', '№ на поръчка', 'id', 'id поръчка',
    'order', 'order id', 'order number', 'order no', 'name'],
  recipient: ['име', 'имена', 'получател', 'име на получател', 'име на получателя', 'клиент', 'име на клиента', 'име на клиент',
    'recipient', 'customer', 'customer name', 'full name', 'shipping name', 'лице за контакт', 'име и фамилия', 'собствено име',
    'first name', 'shipping first name', 'billing first name'],
  last: ['фамилия', 'фамилно име', 'last name', 'surname', 'shipping last name', 'billing last name'],
  phone: ['телефон', 'тел', 'gsm', 'мобилен', 'мобилен телефон', 'телефон за връзка', 'телефон на получателя', 'phone',
    'telephone', 'mobile', 'phone number', 'shipping phone', 'billing phone'],
  email: ['имейл', 'email', 'e mail', 'ел поща', 'електронна поща', 'mail', 'customer email', 'billing email', 'имейл адрес'],
  address: ['адрес', 'адрес за доставка', 'адрес на доставка', 'адрес на получателя', 'улица', 'address', 'shipping address',
    'address 1', 'address1', 'street', 'shipping address1', 'shipping street', 'shipping address 1'],
  address2: ['адрес 2', 'address 2', 'address2', 'shipping address2', 'shipping address 2', 'допълнение към адреса',
    'блок вход етаж апартамент'],
  city: ['град', 'населено място', 'нас място', 'city', 'shipping city', 'град село'],
  postcode: ['пощенски код', 'пк', 'п к', 'zip', 'postcode', 'postal code', 'zip code', 'shipping zip', 'shipping postcode'],
  total: ['общо', 'обща сума', 'сума', 'сума за плащане', 'за плащане', 'наложен платеж', 'сума нп', 'стойност',
    'стойност на поръчката', 'обща стойност', 'крайна сума', 'сума на поръчката', 'total', 'order total', 'amount',
    'cod', 'cod amount', 'grand total', 'total price', 'сума за събиране'],
  payment: ['плащане', 'начин на плащане', 'метод на плащане', 'вид плащане', 'платежен метод', 'payment', 'payment method',
    'payment gateway', 'gateway', 'payment type'],
  shipping: ['доставка', 'начин на доставка', 'метод на доставка', 'вид доставка', 'куриер', 'доставчик', 'shipping',
    'shipping method', 'delivery', 'delivery method', 'carrier'],
  // Recognised only so that they are NOT mistaken for the fields above; never read.
  shipcost: ['цена на доставка', 'цена доставка', 'сума доставка', 'сума за доставка', 'такса доставка', 'такса за доставка',
    'доставка цена', 'стойност на доставка', 'стойност на доставката', 'shipping cost', 'shipping price', 'shipping total',
    'shipping amount', 'статус на доставка', 'статус на доставката'],
  status: ['статус', 'статус на поръчка', 'статус на поръчката', 'status', 'order status', 'financial status',
    'статус на плащане', 'статус на плащането', 'payment status', 'fulfillment status'],
  date: ['дата', 'дата на поръчка', 'дата на поръчката', 'created at', 'date', 'order date', 'created'],
  notes: ['бележка', 'бележки', 'коментар', 'забележка', 'note', 'notes', 'comment', 'comments', 'бележка към поръчката',
    'customer note', 'бележка от клиента', 'коментар към поръчката'],
  item: ['продукт', 'продукти', 'артикул', 'артикули', 'стока', 'име на продукт', 'име на продукта', 'наименование',
    'наименование на продукт', 'item', 'items', 'product', 'products', 'product name', 'lineitem name', 'line item', 'item name'],
  qty: ['количество', 'брой', 'бр', 'к во', 'qty', 'quantity', 'lineitem quantity', 'item quantity'],
  price: ['цена', 'единична цена', 'ед цена', 'цена за брой', 'price', 'unit price', 'lineitem price', 'item price', 'цена на продукт'],
  sku: ['код', 'sku', 'артикулен номер', 'код на продукт', 'код на продукта', 'product code', 'lineitem sku', 'item sku'],
};

// What a column may be called when the shop names our delivery method in it.
const OURS = /фулфил|fulfil/i;
const EXPRESS = /експрес|express/i;
const COD = /наложен|\bcod\b|при доставка|при получаване|в брой|\bcash\b|пощенски паричен/i;
const PAID = /карт|card|онлайн|online|paypal|stripe|банк|bank|превод|transfer|платен|платена|\bpaid\b|apple pay|google pay|epay|mypos|sumup|revolut|виза|visa|mastercard/i;
const SOFIA = /софи|sofia/i;

function norm(s) {
  return String(s == null ? '' : s)
    .toLowerCase()
    .replace(/[ \s]+/g, ' ')
    .replace(/[.:#_\-\/()\[\]"'*,]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// The field a header names, or null.
function fieldFor(header) {
  const h = norm(header);
  if (!h) return null;
  let best = null;
  let bestLen = 0;
  for (const [field, names] of Object.entries(FIELDS)) {
    for (const n of names) {
      if (h === n) return field;
      if (n.length >= 4 && h.includes(n) && n.length > bestLen) {
        best = field;
        bestLen = n.length;
      }
    }
  }
  return best;
}

// Column index per field, from a header row. The first column of a field wins.
function mapHeader(row) {
  const cols = {};
  row.forEach((cell, i) => {
    const f = fieldFor(cell);
    if (f && cols[f] === undefined) cols[f] = i;
  });
  // "Name" is Shopify's order number column; anywhere else it is a person. Only an
  // export that also has a separate recipient column can mean the order by it.
  const hasName = row.findIndex((c) => norm(c) === 'name');
  if (hasName >= 0 && cols.order === hasName && cols.recipient === undefined) {
    cols.recipient = hasName;
    delete cols.order;
  }
  return cols;
}

// How many of the fields that make an order a header row names.
function headerScore(cols) {
  return ['order', 'recipient', 'phone', 'address', 'total', 'payment', 'city', 'item'].filter((f) => cols[f] !== undefined).length;
}

// The header row: the first of the top 15 that names at least two order fields.
function findHeader(rows) {
  let best = { index: -1, cols: {}, score: 0 };
  for (let i = 0; i < Math.min(rows.length, 15); i++) {
    const cols = mapHeader(rows[i] || []);
    const score = headerScore(cols);
    if (score > best.score) best = { index: i, cols, score };
    if (score >= 3) break;
  }
  return best.score >= 2 ? best : { index: -1, cols: {}, score: 0 };
}

// "12,50 €", "1 234,50", "1,234.50", "$12.50", 12.5 -> 12.5; "" -> null
function money(v) {
  if (typeof v === 'number') return isFinite(v) ? Math.round(v * 100) / 100 : null;
  // Punctuation at either end belongs to the currency, not the number: "12,50 лв." ends in a dot.
  let s = String(v == null ? '' : v).replace(/[^\d,.\-]/g, '').replace(/^[.,]+|[.,]+$/g, '');
  if (!s || !/\d/.test(s)) return null;
  const comma = s.lastIndexOf(',');
  const dot = s.lastIndexOf('.');
  if (comma >= 0 && dot >= 0) {
    // Whichever comes last is the decimal mark; the other groups thousands.
    s = comma > dot ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  } else if (comma >= 0) {
    // "1,234" with exactly three digits after is a thousands group only when there is
    // more than one comma; a lone "12,500" in a Bulgarian file is twelve and a half.
    s = (s.match(/,/g) || []).length > 1 ? s.replace(/,/g, '') : s.replace(',', '.');
  }
  const n = parseFloat(s);
  return isFinite(n) ? Math.round(n * 100) / 100 : null;
}

// Excel drops a phone's leading zero when the column is numeric: 888123456 -> 0888123456.
function phone(v) {
  const raw = String(v == null ? '' : v).trim();
  const d = raw.replace(/\D/g, '');
  if (d.length === 9 && /^[89]/.test(d)) return '0' + d;
  if (d.length === 12 && d.startsWith('359') && !raw.startsWith('+')) return '+' + d;
  return raw;
}

function cell(row, cols, f) {
  const i = cols[f];
  if (i === undefined) return '';
  const v = row[i];
  return v == null ? '' : String(v).trim();
}

function paymentFor(text) {
  if (!text) return null;
  if (COD.test(text)) return 'COD';
  if (PAID.test(text)) return 'CARD';
  return null;
}

// The whole file -> { orders, header, notices }. `rows` is an array of arrays of cells.
function parseRows(rows, opts) {
  opts = opts || {};
  const header = findHeader(rows);
  const notices = [];
  if (header.index < 0) {
    return { orders: [], header, notices: ['no-header'] };
  }
  const cols = header.cols;
  const byKey = new Map();
  const orders = [];

  for (let i = header.index + 1; i < rows.length; i++) {
    const row = rows[i] || [];
    if (!row.some((c) => String(c == null ? '' : c).trim() !== '')) continue;

    const no = cell(row, cols, 'order');
    let o = no ? byKey.get(no) : null;
    if (!o) {
      o = {
        key: 'r' + i, no, line: i + 1, recipient: '', phone: '', email: '', street: '', street2: '', city: '', postcode: '',
        totalText: '', paymentText: '', shippingText: '', notes: '', items: [],
      };
      orders.push(o);
      if (no) byKey.set(no, o);
    }
    // A shop that exports one row per product repeats the order's own columns on every
    // row, or leaves them blank after the first; either way the first non-empty value wins.
    const fill = (k, f) => { if (!o[k]) o[k] = cell(row, cols, f); };
    const first = cell(row, cols, 'recipient');
    const last = cell(row, cols, 'last');
    if (!o.recipient && (first || last)) o.recipient = [first, last].filter(Boolean).join(' ');
    if (!o.phone) o.phone = phone(cell(row, cols, 'phone'));
    fill('email', 'email');
    fill('street', 'address');
    fill('street2', 'address2');
    fill('city', 'city');
    fill('postcode', 'postcode');
    fill('totalText', 'total');
    fill('paymentText', 'payment');
    fill('shippingText', 'shipping');
    fill('notes', 'notes');
    const item = cell(row, cols, 'item');
    if (item) {
      o.items.push({
        name: item,
        sku: cell(row, cols, 'sku'),
        quantity: Math.max(1, parseInt(cell(row, cols, 'qty'), 10) || 1),
        price: money(cell(row, cols, 'price')),
      });
    }
  }

  const hasShipping = cols.shipping !== undefined;
  const anyOurs = hasShipping && orders.some((o) => OURS.test(o.shippingText));
  // Our template's "Доставка" says only Стандартна / Експресна - a tier, not a courier.
  const TIER_ONLY = /^\s*(стандарт|експрес|standard|express)\S*\s*$/i;
  if (hasShipping && !anyOurs && orders.some((o) => o.shippingText && !TIER_ONLY.test(o.shippingText))) notices.push('no-ours');
  if (cols.payment === undefined) notices.push('no-payment');
  if (cols.order === undefined) notices.push('no-order-number');
  if (cols.total === undefined) notices.push(cols.price !== undefined ? 'total-from-items' : 'no-total');

  for (const o of orders) {
    let total = money(o.totalText);
    if (total === null && o.items.length && o.items.some((it) => it.price !== null)) {
      total = Math.round(o.items.reduce((a, it) => a + (it.price || 0) * it.quantity, 0) * 100) / 100;
    }
    o.amount = total === null ? '' : total.toFixed(2);
    o.payment = paymentFor(o.paymentText) || (opts.defaultPayment || 'COD');
    o.paymentGuessed = !paymentFor(o.paymentText);
    o.tier = EXPRESS.test(o.shippingText) ? 'Express' : 'Standard';
    o.address = [o.street, o.street2, o.city, o.postcode].filter(Boolean).join(', ');
    o.otherCourier = anyOurs && !OURS.test(o.shippingText);
    o.outsideSofia = !!o.city && !SOFIA.test(o.city);
    o.include = !o.otherCourier && !o.outsideSofia;
  }

  return { orders, header, notices };
}

// What is wrong with an order, in the words the widget shows, or [] when it can go.
function problems(o) {
  const p = [];
  if (!String(o.recipient || '').trim()) p.push('Няма име на получател');
  if (String(o.phone || '').replace(/\D/g, '').length < 6) p.push('Няма телефон');
  if (String(o.address || '').trim().length < 5) p.push('Няма адрес');
  const a = money(o.amount);
  if (o.payment === 'COD' && !(a > 0)) p.push('Няма сума за наложения платеж');
  if (String(o.amount || '').trim() !== '' && a === null) p.push('Сумата не е число');
  return p;
}

// The body for POST int/v1/portal/orders - the same shape the "Нова поръчка" form sends.
function bodyFor(o) {
  const email = String(o.email || '').trim();
  const b = {
    dropoff: {
      address: String(o.address || '').trim(),
      name: String(o.recipient || '').trim(),
      phone: String(o.phone || '').trim(),
    },
    delivery_type: o.tier === 'Express' ? 'Express' : 'Standard',
    payment_method: o.payment === 'COD' ? 'COD' : 'CARD',
    amount: money(o.amount) || 0,
    order_source_id: String(o.no || '').trim(),
    notes: String(o.notes || '').trim(),
    items: (o.items || []).map((it) => ({
      name: it.name, sku: it.sku || '', quantity: it.quantity || 1,
      ...(it.price !== null && it.price !== undefined ? { price: it.price } : {}),
    })),
  };
  // Only a real-looking address is sent: the server validates it as one and would refuse
  // the whole order over a typo in a field the office only uses to write to the customer.
  if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) b.dropoff.email = email;
  return b;
}

// A CSV/TSV text -> rows. Excel in Bulgarian writes ";" - the separator is whichever of
// ; , or tab the first line uses most.
function parseCsv(text) {
  text = String(text || '').replace(/^﻿/, '');
  if (/^sep=(.)\r?\n/i.test(text)) text = text.replace(/^sep=.\r?\n/i, '');
  const firstLine = text.split(/\r?\n/, 1)[0] || '';
  const count = (ch) => firstLine.split(ch).length - 1;
  const sep = [';', ',', '\t'].sort((a, b) => count(b) - count(a))[0];
  const rows = [];
  let row = [];
  let field = '';
  let quoted = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quoted) {
      if (c === '"' && text[i + 1] === '"') { field += '"'; i++; }
      else if (c === '"') quoted = false;
      else field += c;
    } else if (c === '"' && field === '') {
      quoted = true;
    } else if (c === sep) {
      row.push(field); field = '';
    } else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(field); rows.push(row); row = []; field = '';
    } else {
      field += c;
    }
  }
  if (field !== '' || row.length) { row.push(field); rows.push(row); }
  return rows;
}

// Our own template, for a shop whose export cannot be used as it is.
const TEMPLATE = [
  ['Номер на поръчка', 'Получател', 'Телефон', 'Имейл', 'Адрес', 'Град', 'Пощенски код', 'Сума', 'Плащане', 'Доставка', 'Бележка', 'Продукти'],
  ['1001', 'Иван Петров', '+359 111 111 111', '', 'ул. Примерна 1, ет. 2', 'София', '1000', '59.90', 'Наложен платеж', 'Стандартна', 'Звънете преди доставка', 'Подаръчна кошница'],
];

if (typeof module !== 'undefined') {
  module.exports = { FIELDS, norm, fieldFor, mapHeader, findHeader, money, phone, parseRows, problems, bodyFor, parseCsv, TEMPLATE };
}

// ---------------------------------------------------------------- the widget
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const plural = (n, one, many) => `${n} ${Number(n) === 1 ? one : many}`;

let state = { file: '', orders: [], notices: [], error: '', batch: '', done: {} };

const NOTICE = {
  'no-header': ['bad', 'Не открихме колони с поръчки в този файл. Проверете дали първият ред съдържа заглавия (Получател, Телефон, Адрес, Сума…) или използвайте примерния файл.'],
  'no-ours': ['', 'В колоната за доставка никъде не пише „Фулфилия“, затова са избрани всички поръчки. Махнете отметката на тези, които не са за нас.'],
  'no-payment': ['', 'Файлът няма колона за плащане. Всички поръчки са маркирани с наложен платеж. Сменете където е нужно.'],
  'no-order-number': ['', 'Файлът няма номер на поръчка. Ако качите същия файл отново, поръчките ще бъдат създадени втори път.'],
  'total-from-items': ['', 'Файлът няма колона с обща сума. Сумата е сметната от цените на продуктите, без доставката. Проверете я.'],
  'no-total': ['', 'Файлът няма колона със сума. Попълнете сумата за наложения платеж на ръка.'],
};

// The server's reasons are written in English for every caller; the merchant reads Bulgarian.
function serverReason(s) {
  const t = String(s || '').toLowerCase();
  if (t.includes('delivery address')) return 'Адресът не беше намерен. Проверете го и опитайте отново.';
  if (t.includes('delivery price') || t.includes('service rate')) return 'Няма зададена цена за доставка. Свържете се с офиса на Фулфилия.';
  if (t.includes('pickup warehouse')) return 'Адресът ви за взимане не е настроен. Свържете се с офиса на Фулфилия.';
  if (t.includes('not linked to a merchant')) return 'Този вход не е свързан с магазин.';
  if (t.includes('phone')) return 'Телефонът не е приет. Проверете го.';
  if (t.includes('email')) return 'Имейлът не е приет. Проверете го или го изтрийте.';
  if (t.includes('timeout') || t.includes('timed out')) return 'Сървърът не отговори навреме. Опитайте отново.';
  return 'Поръчката не беше създадена. ' + (s ? '(' + s + ')' : '');
}

function readFile(f) {
  if (!f) return;
  state = { file: f.name, orders: [], notices: [], error: '', batch: '', done: {} };
  const ext = String(f.name.split('.').pop() || '').toLowerCase();
  const reader = new FileReader();
  reader.onload = () => {
    try {
      const buf = new Uint8Array(reader.result);
      let rows;
      if (ext === 'csv' || ext === 'txt') {
        // Excel in Bulgarian saves CSV as Windows-1251; anything else is UTF-8.
        let text;
        try { text = new TextDecoder('utf-8', { fatal: true }).decode(buf); } catch (e) { text = new TextDecoder('windows-1251').decode(buf); }
        rows = parseCsv(text);
      } else {
        if (typeof XLSX === 'undefined') throw new Error('xlsx-missing');
        const wb = XLSX.read(buf, { type: 'array' });
        rows = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { header: 1, raw: false, defval: '' });
      }
      const r = parseRows(rows);
      state.orders = r.orders;
      state.notices = r.notices;
      if (!r.orders.length && !r.notices.includes('no-header')) state.error = 'Файлът е празен.';
    } catch (e) {
      state.error = e && e.message === 'xlsx-missing'
        ? 'Excel файлът не може да бъде прочетен в момента. Запазете го като CSV и го качете отново.'
        : 'Файлът не може да бъде прочетен. Качете .xlsx, .xls или .csv.';
    }
    render();
  };
  reader.onerror = () => { state.error = 'Файлът не може да бъде прочетен.'; render(); };
  reader.readAsArrayBuffer(f);
}

// Answers from ImportJS arrive through the model; keep every one, across runs, so a row
// created on the first press is never sent again on the second.
function absorb(m) {
  const r = m.results;
  if (!r || !r.batch || !state.batch || r.batch !== state.batch) return null;
  Object.assign(state.done, r.items || {});
  return r;
}

function statusCell(o) {
  const d = state.done[o.key];
  if (d && d.ok) return `<div class="st ok">✓ Създадена</div>`;
  if (d && d.dup) return `<div class="st ok">Вече е създадена</div>`;
  const p = problems(o);
  if (d && d.error) return `<div class="st bad">${esc(serverReason(d.error))}</div>`;
  if (p.length) return `<div class="st bad">${p.map(esc).join('<br>')}</div>`;
  if (o.otherCourier) return `<div class="st muted">Друг куриер</div>`;
  if (o.outsideSofia) return `<div class="st warn">Извън София?</div>`;
  if (!o.include) return `<div class="st muted">Няма да се създаде</div>`;
  return `<div class="st">Готова</div>`;
}

const sent = (o) => { const d = state.done[o.key]; return !!(d && (d.ok || d.dup)); };
const ready = (o) => o.include && !sent(o) && !problems(o).length;

function orderRow(o) {
  const locked = sent(o);
  const p = problems(o);
  const items = (o.items || []).map((it) => `${it.name}${it.quantity > 1 ? ' ×' + it.quantity : ''}`).join(', ');
  const dis = locked ? ' disabled' : '';
  return `<tr class="${!o.include && !locked ? 'off' : ''}${p.length && o.include && !locked ? ' bad' : ''}">` +
    `<td><input type="checkbox" data-k="${o.key}" data-f="include"${o.include || locked ? ' checked' : ''}${dis} aria-label="Създай"></td>` +
    `<td><div class="no">${esc(o.no || '—')}</div></td>` +
    `<td><input data-k="${o.key}" data-f="recipient" value="${esc(o.recipient)}"${dis}>${items ? `<div class="items">${esc(items)}</div>` : ''}</td>` +
    `<td><input data-k="${o.key}" data-f="phone" value="${esc(o.phone)}"${dis}></td>` +
    `<td style="min-width:260px"><input data-k="${o.key}" data-f="address" value="${esc(o.address)}"${dis}></td>` +
    `<td><input class="amt" data-k="${o.key}" data-f="amount" value="${esc(o.amount)}"${dis}></td>` +
    `<td><select data-k="${o.key}" data-f="payment"${dis}><option value="COD"${o.payment === 'COD' ? ' selected' : ''}>Наложен платеж</option><option value="CARD"${o.payment !== 'COD' ? ' selected' : ''}>Платена</option></select></td>` +
    `<td><select data-k="${o.key}" data-f="tier"${dis}><option value="Standard"${o.tier !== 'Express' ? ' selected' : ''}>Стандартна</option><option value="Express"${o.tier === 'Express' ? ' selected' : ''}>Експресна</option></select></td>` +
    `<td style="min-width:150px">${statusCell(o)}</td></tr>`;
}

function render() {
  const m = appsmith.model || {};
  document.documentElement.dataset.theme = 'light';
  const INK = '#1D1D1F';
  document.body.style.color = INK;
  const run = absorb(m);
  const running = !!(run && run.running);

  const intro = `<div class="row"><div><h2 style="color:${INK}">Качи поръчки</h2>` +
    `<div class="sub">от Excel или CSV файл, например експорт от вашия онлайн магазин</div></div></div>`;

  const drop = `<div class="card"><label class="drop" id="drop">` +
    `<input type="file" id="file" accept=".xlsx,.xls,.csv">` +
    `<strong>${state.file ? 'Изберете друг файл' : 'Изберете файл'}</strong>` +
    `<span class="hint">${state.file ? esc(state.file) : '.xlsx, .xls или .csv, или го пуснете тук'}</span></label>` +
    `<div class="links"><button type="button" class="link" data-act="template">Свали примерен файл</button>` +
    `<span>Всеки ред е една поръчка. Задължителни са получател, телефон и адрес, а за наложен платеж и сума.</span></div></div>`;

  let body = '';
  if (state.error) body += `<div class="notice bad">${esc(state.error)}</div>`;
  state.notices.forEach((k) => { const n = NOTICE[k]; if (n) body += `<div class="notice ${n[0]}">${n[1]}</div>`; });

  if (state.orders.length) {
    const toSend = state.orders.filter(ready);
    const created = state.orders.filter((o) => { const d = state.done[o.key]; return d && d.ok; }).length;
    const dups = state.orders.filter((o) => { const d = state.done[o.key]; return d && d.dup; }).length;
    const failed = state.orders.filter((o) => { const d = state.done[o.key]; return d && d.error; }).length;
    const withProblems = state.orders.filter((o) => o.include && !sent(o) && problems(o).length).length;
    const skipped = state.orders.filter((o) => !o.include && !sent(o)).length;

    const chips = `<div class="chips">` +
      `<span class="chip">${plural(state.orders.length, 'поръчка във файла', 'поръчки във файла')}</span>` +
      (toSend.length ? `<span class="chip ok">${plural(toSend.length, 'готова', 'готови')}</span>` : '') +
      (withProblems ? `<span class="chip bad">${plural(withProblems, 'за поправка', 'за поправка')}</span>` : '') +
      (skipped ? `<span class="chip">${plural(skipped, 'пропусната', 'пропуснати')}</span>` : '') +
      `</div>`;

    let progress = '';
    if (running) {
      const n = Object.keys((run && run.items) || {}).length;
      progress = `<div class="notice">Създаване… ${n} от ${run.total}</div>`;
    } else if (created || dups || failed) {
      progress = `<div class="notice ${failed ? 'bad' : 'ok'}">` +
        [created ? plural(created, 'поръчка е създадена', 'поръчки са създадени') : '',
         dups ? plural(dups, 'вече беше създадена', 'вече бяха създадени') + ' по-рано' : '',
         failed ? plural(failed, 'не беше създадена', 'не бяха създадени') + '. Поправете ги и натиснете „Създай“ отново' : '']
          .filter(Boolean).map((t) => `<span>${t}</span>`).join(' · ') + `</div>`;
    }

    body += `<div class="card"><div class="hd"><h3>Поръчки</h3>${chips}</div>` +
      `<div class="tablewrap"><table><thead><tr><th></th><th>№</th><th>Получател</th><th>Телефон</th><th>Адрес</th>` +
      `<th>Сума €</th><th>Плащане</th><th>Доставка</th><th>Статус</th></tr></thead><tbody>` +
      state.orders.map(orderRow).join('') + `</tbody></table></div>` +
      progress +
      `<div class="foot"><span class="note">Сумата е това, което куриерът събира от получателя при наложен платеж. ` +
      `При „Платена“ не се събират пари.</span>` +
      `<span style="display:flex;gap:8px;flex-wrap:wrap">` +
      (created || dups ? `<button type="button" class="btn" data-act="orders">Към поръчките</button>` : '') +
      `<button type="button" class="btn primary" data-act="create"${running || !toSend.length ? ' disabled' : ''}>` +
      `${running ? 'Създаване…' : toSend.length ? 'Създай ' + plural(toSend.length, 'поръчка', 'поръчки') : 'Няма поръчки за създаване'}</button></span></div></div>`;
  }

  document.getElementById('bo-import').innerHTML = `<div class="wrap">${intro}${drop}${body}</div>`;
  wire(running);
}

function wire(running) {
  const input = document.getElementById('file');
  const drop = document.getElementById('drop');
  input.addEventListener('change', () => readFile(input.files && input.files[0]));
  ['dragenter', 'dragover'].forEach((e) => drop.addEventListener(e, (ev) => { ev.preventDefault(); drop.classList.add('over'); }));
  ['dragleave', 'drop'].forEach((e) => drop.addEventListener(e, (ev) => { ev.preventDefault(); drop.classList.remove('over'); }));
  drop.addEventListener('drop', (ev) => readFile(ev.dataTransfer && ev.dataTransfer.files && ev.dataTransfer.files[0]));

  // Edits land in the order on "change" (leaving the field), not on every keystroke:
  // a redraw per key would take the cursor out of the box being typed in.
  document.querySelectorAll('[data-k][data-f]').forEach((el) => el.addEventListener('change', () => {
    const o = state.orders.find((x) => x.key === el.dataset.k);
    if (!o || sent(o)) return;
    const f = el.dataset.f;
    o[f] = el.type === 'checkbox' ? el.checked : el.value;
    // A fixed row forgets the server's last refusal; the next press is a fresh try.
    if (state.done[o.key] && state.done[o.key].error) delete state.done[o.key];
    render();
  }));

  document.querySelectorAll('[data-act]').forEach((el) => el.addEventListener('click', (ev) => {
    ev.preventDefault();
    const act = el.dataset.act;
    if (act === 'create') {
      if (running) return;
      const list = state.orders.filter(ready);
      if (!list.length) return;
      list.forEach((o) => { if (state.done[o.key]) delete state.done[o.key]; });
      state.batch = 'b' + Date.now();
      appsmith.updateModel({ action: 'create', batch: state.batch, orders: list.map((o) => ({ key: o.key, body: bodyFor(o) })) });
      appsmith.triggerEvent('onAction');
      render();
    } else if (act === 'template') {
      if (typeof XLSX !== 'undefined') {
        const wb = XLSX.utils.book_new();
        const ws = XLSX.utils.aoa_to_sheet(TEMPLATE);
        ws['!cols'] = TEMPLATE[0].map((h) => ({ wch: Math.max(12, h.length + 4) }));
        XLSX.utils.book_append_sheet(wb, ws, 'Поръчки');
        const b64 = XLSX.write(wb, { type: 'base64', bookType: 'xlsx' });
        appsmith.updateModel({ action: 'template', data: 'data:application/vnd.openxmlformats-officedocument.spreadsheetml.sheet;base64,' + b64, filename: 'fulfilya-poruchki.xlsx', mime: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
      } else {
        const csv = '﻿' + TEMPLATE.map((r) => r.map((c) => /[;"\n]/.test(c) ? '"' + c.replace(/"/g, '""') + '"' : c).join(';')).join('\r\n');
        appsmith.updateModel({ action: 'template', data: csv, filename: 'fulfilya-poruchki.csv', mime: 'text/csv' });
      }
      appsmith.triggerEvent('onAction');
    } else if (act === 'orders') {
      appsmith.updateModel({ action: 'orders' });
      appsmith.triggerEvent('onAction');
    }
  }));
}

appsmith.onReady(render);
appsmith.onModelChange(render);

