const BO_DAYS = Object.assign({}, { 'Нд': 'Sun', 'Пн': 'Mon', 'Вт': 'Tue', 'Ср': 'Wed', 'Чт': 'Thu', 'Пт': 'Fri', 'Сб': 'Sat' }, { 'неделя': 'Sunday', 'понеделник': 'Monday', 'вторник': 'Tuesday', 'сряда': 'Wednesday', 'четвъртък': 'Thursday', 'петък': 'Friday', 'събота': 'Saturday' });
