const BO_RULES = [[/^(\d+) поръчки? във файла$/, '$1 in the file'], [/^(\d+) готов[аи]$/, '$1 ready'], [/^(\d+) за поправка$/, '$1 to fix'], [/^(\d+) пропуснат[аи]$/, '$1 skipped'], [/^Създаване… (\d+) от (\d+)$/, 'Creating… $1 of $2'], [/^Създай 1 поръчка$/, 'Create 1 order'], [/^Създай (\d+) поръчки$/, 'Create $1 orders'], [/^(\d+) поръчк[аи] (е|са) създаден[аи]$/, '$1 created'], [/^(\d+) вече (беше|бяха) създаден[аи] по-рано$/, '$1 already created earlier'], [/^(\d+) не (беше|бяха) създаден[аи]\. Поправете ги и натиснете „Създай“ отново$/, '$1 not created. Fix them and press "Create" again'], [/^Поръчката не беше създадена\. (.*)$/, 'The order was not created. $1'], [/^\+(\d+) днес$/, '+$1 today'], [/^(\d+) чакат куриер$/, '$1 awaiting courier'], [/^(\d+) поръчки с НП$/, '$1 orders with COD'], [/^(\d+) поръчки$/, '$1 orders'], [/^(\d+) върнати · (\d+) отказани$/, '$1 returned · $2 cancelled'], [/^за изплащане (.+)$/, 'to pay out $1'], [/^(\d+) дни · (\d+) поръчки$/, '$1 days · $2 orders'], [/^за (\d+) дни · (\d+) поръчки$/, 'over $1 days · $2 orders'], [/^за (\d+) дни$/, 'over $1 days'], [/^(\d+) бр\.$/, '$1 pcs'], [/^Бр\.: (.+)$/, 'Qty: $1'], [/^Добро утро, (.+)$/, 'Good morning, $1'], [/^Добър ден, (.+)$/, 'Good afternoon, $1'], [/^Добър вечер, (.+)$/, 'Good evening, $1'], [/^(.+) · по ден на доставка$/, '$1 · by delivery day'], [/^изплатено (.+)$/, 'paid out $1'], [/^предстои (.+)$/, 'coming $1'], [/^(\d+) изплащания$/, '$1 payouts'], [/^1 изплащане$/, '1 payout'], [/^1 поръчка$/, '1 order'], [/^(\d+) доставени поръчки$/, '$1 delivered orders'], [/^1 доставена поръчка$/, '1 delivered order'], [/^за (\d+) поръчки$/, 'for $1 orders'], [/^за 1 поръчка$/, 'for 1 order'], [/^в брой (.+) · с карта (.+)$/, 'cash $1 · card $2'], [/^доставки (.+) · такса НП (.+)$/, 'deliveries $1 · COD fee $2'], [/^разминаване (.+) — провери$/, 'difference $1 — check'], [/^За превод към (.+)$/, 'To transfer to $1'], [/^по 1 поръчка$/, 'for 1 order'], [/^по (\d+) поръчки$/, 'for $1 orde